sys_atf_step.inputs:
(function(outputs, steps, stepResult) {
  var env = new x_fed_day2_ops.Day2Env();
  if (!env.isTestMode()) { stepResult.setFailed('x_fed_day2_ops.test_mode must be true on a declared non-prod instance'); return; }

  var sam = new x_fed_day2_ops.SamCorrelationClient();
  var status = sam.getRequestStatus('ATF-SAM-0007');
  if (!status.ok || status.status !== 'approved') {
    stepResult.setFailed('getRequestStatus should return the canned approved status in test_mode: ' + JSON.stringify(status));
    return;
  }
  var pulled = sam.fetchIdentityRequest('ATF-SAM-0007');
  if (!pulled.ok) {
    stepResult.setFailed('fetchIdentityRequest should return a canned approval in test_mode: ' + pulled.reason);
    return;
  }
  stepResult.setSuccess();
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  var savedTestMode = gs.getProperty('x_fed_day2_ops.test_mode', 'false');
  try {
    gs.setProperty('x_fed_day2_ops.test_mode', 'false');
    var sam = new x_fed_day2_ops.SamCorrelationClient();

    var status = sam.getRequestStatus('ATF-SAM-0007');
    if (status.ok && status.status === 'approved') {
      stepResult.setFailed('getRequestStatus should not report "approved" in live mode with no SAM reachable — closure would be unproven');
      return;
    }

    var pulled = sam.fetchIdentityRequest('ATF-SAM-0007');
    if (pulled.ok) {
      stepResult.setFailed('fetchIdentityRequest should refuse in live mode until a tenant wires it — got ok:true');
      return;
    }
    stepResult.setSuccess();
  } finally {
    gs.setProperty('x_fed_day2_ops.test_mode', savedTestMode);
  }
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  var env = new x_fed_day2_ops.Day2Env();
  if (!env.isTestMode()) { stepResult.setFailed('test_mode should have been restored to true after step 200'); return; }
  var sam = new x_fed_day2_ops.SamCorrelationClient();
  var status = sam.getRequestStatus('ATF-SAM-0007');
  status.ok && status.status === 'approved'
    ? stepResult.setSuccess()
    : stepResult.setFailed('canned test_mode response did not return after restoring the property');
})(outputs, steps, stepResult);
